def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    Rules:
    - The text is split into lines; each line is split at its first "=".
    - Whitespace around the name and around the value is stripped.
    - Blank lines, lines starting with "#" (after stripping), and lines
      without "=" are ignored.
    - Key matching is exact and case-sensitive.
    - The value is everything after the first "=", so it may itself
      contain "=".
    - If the key appears more than once, the first occurrence wins.
    - Returns "" when the key is absent (an empty value also yields "").
    - Does not read files; `text` is the only input.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2\nc=3", "b") == "2"


def test_first_and_last_lines() -> None:
    text = "a=1\nb=2\nc=3"
    assert config_value(text, "a") == "1"
    assert config_value(text, "c") == "3"


def test_absent_key() -> None:
    assert config_value("a=1\nb=2", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_stripped() -> None:
    assert config_value("  name  =   value with spaces  \n", "name") == "value with spaces"


def test_value_contains_equals() -> None:
    assert config_value("url=http://x/?a=b&c=d", "url") == "http://x/?a=b&c=d"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_comment_lines_ignored() -> None:
    assert config_value("# a=1\nb=2", "a") == ""
    assert config_value("  # a=1\na=5", "a") == "5"


def test_blank_and_malformed_lines_ignored() -> None:
    text = "\n   \njunk line\na=1\n"
    assert config_value(text, "a") == "1"
    assert config_value(text, "junk line") == ""


def test_duplicate_key_first_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_key_match_is_exact() -> None:
    text = "abc=1\nab=2\nA=3"
    assert config_value(text, "ab") == "2"
    assert config_value(text, "a") == ""
    assert config_value(text, "A") == "3"


def test_value_not_matched_as_key() -> None:
    assert config_value("a=b\nb=", "b") == ""
    assert config_value("a=b", "b") == ""


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"
